#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "skcms.h"

int main(int argc, char** argv) {
    FILE* fp = fopen(argv[1], "rb");
    fseek(fp, 0L, SEEK_END);
    long slen = ftell(fp);
    rewind(fp);
    void* data = malloc(slen);
    size_t size = fread(data, 1, slen, fp);
    fclose(fp);

    skcms_ICCProfile p;
    int result = skcms_Parse(data, size, &p);
    printf("Parse result: %d\n", result);
    if (result) {
        printf("has_A2B: %d\n", p.has_A2B);
        printf("A2B input_channels: %u\n", p.A2B.input_channels);
        printf("A2B grid_points: %u %u %u %u\n", p.A2B.grid_points[0], p.A2B.grid_points[1], p.A2B.grid_points[2], p.A2B.grid_points[3]);
    }
    return 0;
}
EOF
